  expected jsonb;
  actual assessment_questions%ROWTYPE;
BEGIN
  LOCK TABLE assessment_questions IN EXCLUSIVE MODE;
  FOR expected IN SELECT value FROM jsonb_array_elements(seed) LOOP
    SELECT * INTO actual FROM assessment_questions WHERE question_id = expected->>'id';
    IF NOT FOUND OR actual.prompt IS DISTINCT FROM expected->>'prompt'
      OR jsonb_array_length(actual.options) <> jsonb_array_length(expected->'options')
      OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(expected->'options') wanted
        WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(actual.options) saved
          WHERE saved->>'id' = wanted->>'id' AND saved->>'label' = wanted->>'label')
      )
    THEN
      RAISE EXCEPTION 'Question % differs from the original reviewed seed; review it before migrating.', expected->>'id';
    END IF;
    UPDATE assessment_questions SET
      legacy_scoring_backup = jsonb_build_object('prompt', prompt, 'options', options, 'status', status, 'updatedAt', updated_at),
      routing_config = expected->'routing',
      options = (
        SELECT jsonb_agg(mapped.value ORDER BY old.ordinality)
        FROM jsonb_array_elements(actual.options) WITH ORDINALITY old(value, ordinality)
        JOIN jsonb_array_elements(expected->'options') mapped(value)
          ON mapped.value->>'id' = old.value->>'id'
      ),
      updated_at = CURRENT_TIMESTAMP
    WHERE question_id = expected->>'id';
  END LOOP;
